class Solution {
  public List<String> generateValidStrings(int n, int k) {
    List<String> res = new ArrayList<>();
    build(new char[n], 0, 0, k, res);
    return res;
  }

  private void build(char[] cur, int pos, int cost, int k, List<String> res) {
    if (pos == cur.length) {
      res.add(new String(cur));
      return;
    }
    cur[pos] = '0';
    build(cur, pos + 1, cost, k, res);
    if ((pos == 0 || cur[pos - 1] == '0') && cost + pos <= k) {
      cur[pos] = '1';
      build(cur, pos + 1, cost + pos, k, res);
    }
  }
}
